#!/usr/bin/env node
/**
 * Renders apps/docs/og/og-card.html, a standalone 1280x640 page with no
 * Starlight chrome, into apps/docs/public/og.png: the image
 * astro.config.mjs wires up as the site's `og:image` and `twitter:image`,
 * and the same file GitHub's own repository social preview upload uses.
 *
 * Not part of the docs build: like e2e/scripts/generate-example-screenshots.mjs,
 * this is a checked-in asset, regenerated by hand when the card's own
 * design changes, not derived data recomputed on every build. Run with
 * `pnpm --filter @rpxl/riffle-e2e run generate-og-image`. The card page is
 * self-contained (inline styles, no scripts, no external assets), so it is
 * opened straight from disk: no docs build and no server are needed, and
 * the page itself is never part of the published site.
 */
import { chromium } from '@playwright/test'
import { mkdir } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const repoRoot = fileURLToPath(new URL('../..', import.meta.url))
const docsDir = join(repoRoot, 'apps/docs')
const cardUrl = pathToFileURL(join(docsDir, 'og/og-card.html')).href
const outPath = join(docsDir, 'public/og.png')

async function main() {
  const browser = await chromium.launch()
  try {
    const page = await browser.newPage({
      viewport: { width: 1280, height: 640 },
      deviceScaleFactor: 1,
    })
    await page.goto(cardUrl)
    const card = page.locator('#og-card')
    await card.waitFor({ state: 'visible' })

    const box = await card.boundingBox()
    if (!box || Math.round(box.width) !== 1280 || Math.round(box.height) !== 640) {
      throw new Error(
        `generate-og-image: #og-card is ${box?.width}x${box?.height}, expected exactly 1280x640`,
      )
    }

    await mkdir(dirname(outPath), { recursive: true })
    await card.screenshot({ path: outPath })
    console.log(`Wrote ${outPath}`)
  } finally {
    await browser.close()
  }
}

main().catch((error) => {
  console.error(error)
  process.exit(1)
})
